describe('Retry Button Functionality', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application
    });

    it('should display retry button when network request times out', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 408, // Simulating a timeout
            delay: 1000
        }).as('getData');

        cy.get('button#load-data').click(); // Assuming there's a button to load data
        cy.wait('@getData');

        cy.get('div#error-message').should('be.visible').and('contain', 'Request timed out');
        cy.get('button#retry-button').should('be.visible');
    });

    it('should successfully fetch data after retrying', () => {
        cy.intercept('GET', '/api/data', {
            statusCode: 200,
            body: { data: 'Success' }
        }).as('getData');

        cy.intercept('GET', '/api/data', {
            statusCode: 408, // First request times out
            delay: 1000
        }).as('getTimeout');

        cy.get('button#load-data').click(); // First request
        cy.wait('@getTimeout');

        cy.get('button#retry-button').click(); // Retry button click
        cy.wait('@getData');

        cy.get('div#data-display').should('be.visible').and('contain', 'Success');
    });
});
